package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
final class KnowledgeDraftsAcceptance {
    static String api(String id){return "/api/openservice/knowledge/"+id+"/draft";}
    static Map<String,Object> result(java.net.http.HttpResponse<byte[]> response)throws Exception{return TransferAcceptance.result(response,200);}
    static Map<String,Object> action(Map<String,Object> view,String operation){return map("operation",operation,"version",view.get("version"),"review",view.get("review"),"confirm",true);}
    static String seed(Store store)throws Exception{try(var db=store.open()){String actor=PlatformFoundationTest.bind(db);String id=KnowledgeSearchAcceptance.article(db,actor,"First knowledge title","Original instructions <script>");Service.update(db,"kb_knowledge",Service.record(db,"kb_knowledge",id),map("short_description","Current title","text","Current instructions","category","Preserved category"),"admin","admin",null);PublishedKnowledge.publish(db,actor,id);Service.update(db,"kb_knowledge",Service.record(db,"kb_knowledge",id),map("text","Unpublished work"),"admin","admin",null);db.connection.commit();return id;}}
    static void run(WorkflowSupport h)throws Exception{
        h.account("DraftReader","reader");String id=seed(h.store),path=api(id);var view=result(h.get(path+"?version=1",auth("admin")));assertEquals("Unpublished work",object(view.get("draft")).get("text"));assertEquals("Original instructions <script>",object(view.get("source")).get("content"));assertEquals("Current instructions",object(view.get("latest")).get("content"));Map<String,Object> access;try(var db=h.store.open()){access=RecordAccess.status(db,id);}
        var recovered=result(h.json("POST",path,action(view,"recover"),auth("admin")));assertEquals(1,recovered.get("source_version"));assertEquals(409,h.json("POST",path,action(view,"recover"),auth("admin")).statusCode());try(var db=h.store.open()){PlatformFoundationTest.bind(db);var data=object(Service.record(db,"kb_knowledge",id).get("data"));assertEquals("Original instructions <script>",data.get("text"));assertEquals("Preserved category",data.get("category"));assertEquals(access,RecordAccess.status(db,id));assertEquals(2,db.count("SELECT COUNT(*) FROM os_publication WHERE article_id=?",id));assertEquals(1,db.count("SELECT COUNT(*) FROM os_event WHERE record_id=? AND action='knowledge.draft_recovered'",id));}
        assertEquals("Current instructions",object(result(h.get("/api/openservice/knowledge/"+id,auth("DraftReader"))).get("article")).get("content"));new Store(h.environment);view=result(h.get(path,auth("admin")));assertEquals(200,h.json("PATCH","/api/now/table/kb_knowledge/"+id,map("text","Edited recovered instructions"),auth("admin")).statusCode());assertEquals(409,h.json("POST",path,action(view,"publish"),auth("admin")).statusCode());
        view=result(h.get(path,auth("admin")));assertEquals(3,result(h.json("POST",path,action(view,"publish"),auth("admin"))).get("version"));assertEquals(409,h.json("POST",path,action(view,"publish"),auth("admin")).statusCode());assertEquals("Edited recovered instructions",object(result(h.get("/api/openservice/knowledge/"+id,auth("DraftReader"))).get("article")).get("content"));try(var db=h.store.open()){assertEquals("Original instructions <script>",db.one("SELECT content FROM os_publication WHERE article_id=? AND version=1",id).get("content"));}
        result(h.json("POST","/api/openservice/operations/knowledge/"+id,map("operation","retire"),auth("admin")));view=result(h.get(path+"?version=1",auth("admin")));result(h.json("POST",path,action(view,"recover"),auth("admin")));assertEquals(404,h.get("/api/openservice/knowledge/"+id,auth("DraftReader")).statusCode());view=result(h.get(path,auth("admin")));result(h.json("POST",path,action(view,"publish"),auth("admin")));assertEquals(200,h.get("/api/openservice/knowledge/"+id,auth("DraftReader")).statusCode());
    }
    static void boundaries(WorkflowSupport h)throws Exception{
        h.account("DraftReader","reader");h.account("DraftAgent","agent");String id;try(var db=h.store.open()){PlatformFoundationTest.bind(db);id=Service.create(db,"kb_knowledge",map("short_description","New draft","text","New body"),"admin").get("sys_id").toString();db.connection.commit();}String path=api(id);var view=result(h.get(path,auth("admin")));assertTrue(object(view.get("latest")).isEmpty());assertTrue(object(view.get("source")).isEmpty());assertEquals(400,h.json("POST",path,action(view,"recover"),auth("admin")).statusCode());assertEquals(404,h.get(path+"?version=1",auth("admin")).statusCode());assertEquals(401,h.get(path,null).statusCode());for(String role:List.of("DraftReader","DraftAgent")){assertEquals(403,h.get(path,auth(role)).statusCode());assertEquals(403,h.json("POST",path,action(view,"publish"),auth(role)).statusCode());}assertEquals(405,h.json("PUT",path,map(),auth("admin")).statusCode());assertEquals(400,h.get(path+"?bad=x",auth("admin")).statusCode());assertEquals(400,h.get(path+"?version=-1",auth("admin")).statusCode());assertEquals(400,h.get(path+"?version=1&version=2",auth("admin")).statusCode());assertEquals(404,h.get(api(id()),auth("admin")).statusCode());
        for(var bad:List.of(map(),map("operation","recover","version","1","review","x","confirm",true),map("operation","bad","version",0,"review","x","confirm",true),map("operation","publish","version",0,"review","x","confirm",false))){assertEquals(400,h.json("POST",path,bad,auth("admin")).statusCode());}var stale=action(view,"publish");stale.put("review","stale");assertEquals(409,h.json("POST",path,stale,auth("admin")).statusCode());
        String browser="/admin/knowledge/"+id+"/draft";assertEquals(403,h.form(browser,action(view,"publish"),auth("admin")).statusCode());var form=action(view,"publish");form.put("confirm","false");assertEquals(400,h.protectedForm(browser,form,auth("admin")).statusCode());form.put("confirm","true");assertEquals(302,h.protectedForm(browser,form,auth("admin")).statusCode());assertEquals(1,object(result(h.get(path,auth("admin"))).get("latest")).get("version"));
        Map<String,Object> schema;try(var db=h.store.open()){schema=Service.schema(db,"kb_knowledge");}
        try{
            view=result(h.get(path,auth("admin")));try(var db=h.store.open()){String actor=PlatformFoundationTest.bind(db);RecordAccess.change(db,Service.record(db,"kb_knowledge",id),actor,map("visibility","private","owner_id",actor));db.connection.commit();}assertEquals(409,h.json("POST",path,action(view,"publish"),auth("admin")).statusCode());view=result(h.get(path,auth("admin")));assertEquals(400,h.json("POST",path,action(view,"publish"),auth("admin")).statusCode());result(h.json("POST",path,action(view,"recover"),auth("admin")));
            for(String operation:List.of("read","update")){try(var db=h.store.open()){var blocked=new LinkedHashMap<>(schema);blocked.put("record_roles",map(operation,List.of("agent")));db.update("UPDATE os_schema SET definition="+db.jsonParameter()+" WHERE name='kb_knowledge'",JSON.writeValueAsString(blocked));db.connection.commit();}assertEquals(403,h.get(path,auth("admin")).statusCode());}
            try(var db=h.store.open()){var changed=new LinkedHashMap<>(schema);changed.put("field_rules",map("text",map("type","string","max_length",2)));db.update("UPDATE os_schema SET definition="+db.jsonParameter()+" WHERE name='kb_knowledge'",JSON.writeValueAsString(changed));db.connection.commit();}view=result(h.get(path,auth("admin")));assertEquals(400,h.json("POST",path,action(view,"recover"),auth("admin")).statusCode());try(var db=h.store.open()){assertEquals(1,db.count("SELECT COUNT(*) FROM os_publication WHERE article_id=?",id));}
        }finally{try(var db=h.store.open()){db.update("UPDATE os_schema SET definition="+db.jsonParameter()+" WHERE name='kb_knowledge'",JSON.writeValueAsString(schema));db.connection.commit();}}
    }
}
